		return
	}

	// Skip header
	header := records[0]
	// Map column indices
	colMap := make(map[string]int)
	for i, h := range header {
		colMap[strings.TrimSpace(h)] = i
	}

	var results []Person

	for i := 1; i < len(records); i++ {
