		}

		motherName := row[colMap["Mother"]]
		if motherName != "null" && motherName != "" {
			relatives = append(relatives, parseRelative(motherName, "Mother"))
		}

		brotherName := row[colMap["Brother"]]
		if brotherName != "null" && brotherName != "" {
