        100,
        49,
        4410 // 100 * 49 * 0.9
    );

    // Test case 4: quantity >= 50 (25% discount)
    // Boundary: quantity = 50
    runTest(
        "25% discount for quantity 50",
        100,
        50,
        3750 // 100 * 50 * 0.75
    );
}

